import{_ as a,o as n,c as e,am as i}from"./chunks/framework._FJXuPhs.js";const c=JSON.parse('{"title":"AI 框架选型对比","description":"","frontmatter":{"title":"AI 框架选型对比","excerpt":"Spring AI / Spring AI Alibaba / LangChain4j / AgentScope Java / Google ADK 五款 Java AI 框架的定位、差异与选型指南","date":"2026-05-05 22:30:00","updated":"2026-05-05 22:30:00"},"headers":[],"relativePath":"框架/AI 框架/AI 框架选型对比.md","filePath":"框架/AI 框架/AI 框架选型对比.md","lastUpdated":null}'),s={name:"框架/AI 框架/AI 框架选型对比.md"};function l(r,t,d,g,p,h){return n(),e("div",null,[...t[0]||(t[0]=[i(`<hr><h2 id="知识点清单" tabindex="-1">知识点清单 <a class="header-anchor" href="#知识点清单" aria-label="Permalink to &quot;知识点清单&quot;">​</a></h2><ul><li>[ ] 五款框架各自的定位与核心能力</li><li>[ ] LangChain4j vs Spring AI Alibaba 的本质区别</li><li>[ ] 多智能体编排：谁支持、怎么用</li><li>[ ] 模型接入广度对比</li><li>[ ] 企业级能力（安全沙箱、人工审批、会话持久化）</li><li>[ ] 技术选型决策树</li><li>[ ] 是否可以混用？有什么坑？</li></ul><hr><h2 id="一、框架定位一句话" tabindex="-1">一、框架定位一句话 <a class="header-anchor" href="#一、框架定位一句话" aria-label="Permalink to &quot;一、框架定位一句话&quot;">​</a></h2><table tabindex="0"><thead><tr><th>框架</th><th>一句话定位</th><th>类比</th></tr></thead><tbody><tr><td><strong>Spring AI</strong></td><td>Spring 官方的 LLM 集成标准抽象层</td><td>Java 界的 AI JDBC</td></tr><tr><td><strong>Spring AI Alibaba</strong></td><td>阿里开源的 Agentic AI 应用平台</td><td>Java 界的 LangGraph + Dify</td></tr><tr><td><strong>LangChain4j</strong></td><td>JVM 生态最成熟的 LLM 集成工具箱</td><td>Java 界的 LangChain</td></tr><tr><td><strong>AgentScope Java</strong></td><td>企业级多智能体运行时引擎</td><td>Java 界的 CrewAI</td></tr><tr><td><strong>Google ADK</strong></td><td>Google 的多语言 AI Agent 开发套件</td><td>Google 版 Agent SDK</td></tr></tbody></table><p><strong>简单总结：LangChain4j 帮你&quot;用上 LLM&quot;，Spring AI Alibaba 帮你&quot;用好 Agent&quot;。</strong></p><hr><h2 id="二、核心维度对比" tabindex="-1">二、核心维度对比 <a class="header-anchor" href="#二、核心维度对比" aria-label="Permalink to &quot;二、核心维度对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th style="text-align:center;">Spring AI</th><th style="text-align:center;">LangChain4j</th><th style="text-align:center;">Spring AI Alibaba</th><th style="text-align:center;">AgentScope Java</th><th style="text-align:center;">Google ADK</th></tr></thead><tbody><tr><td><strong>模型接入</strong></td><td style="text-align:center;">20+</td><td style="text-align:center;">20+</td><td style="text-align:center;">阿里云为主</td><td style="text-align:center;">阿里云为主</td><td style="text-align:center;">Gemini 为主</td></tr><tr><td><strong>向量数据库</strong></td><td style="text-align:center;">15+</td><td style="text-align:center;">30+</td><td style="text-align:center;">依托 Spring AI</td><td style="text-align:center;">无独立抽象</td><td style="text-align:center;">无独立抽象</td></tr><tr><td><strong>多 Agent 编排</strong></td><td style="text-align:center;">无</td><td style="text-align:center;">有限</td><td style="text-align:center;">7 种模式</td><td style="text-align:center;">7 种模式</td><td style="text-align:center;">Agent 链</td></tr><tr><td><strong>安全沙箱</strong></td><td style="text-align:center;">无</td><td style="text-align:center;">无</td><td style="text-align:center;">依托 AgentScope</td><td style="text-align:center;"><strong>内置 Docker</strong></td><td style="text-align:center;">容器执行</td></tr><tr><td><strong>Human-in-the-Loop</strong></td><td style="text-align:center;">无</td><td style="text-align:center;">无</td><td style="text-align:center;">支持</td><td style="text-align:center;">interrupt()</td><td style="text-align:center;">ToolConfirmation</td></tr><tr><td><strong>会话持久化</strong></td><td style="text-align:center;">JDBC/Redis</td><td style="text-align:center;">自实现</td><td style="text-align:center;">RocketMQ</td><td style="text-align:center;">RocketMQ</td><td style="text-align:center;">Firestore 等</td></tr><tr><td><strong>可视化工具</strong></td><td style="text-align:center;">无</td><td style="text-align:center;">无</td><td style="text-align:center;">Admin 工具</td><td style="text-align:center;">无</td><td style="text-align:center;">dev UI</td></tr><tr><td><strong>与 Spring 解耦</strong></td><td style="text-align:center;">绑定 Spring</td><td style="text-align:center;"><strong>可独立使用</strong></td><td style="text-align:center;">绑定 Spring Boot</td><td style="text-align:center;"><strong>可独立使用</strong></td><td style="text-align:center;">绑定 Google</td></tr><tr><td><strong>版本</strong></td><td style="text-align:center;">1.1.4</td><td style="text-align:center;">1.14.0</td><td style="text-align:center;">1.1.2.2</td><td style="text-align:center;">1.0.10</td><td style="text-align:center;">1.0.0</td></tr><tr><td><strong>成熟度</strong></td><td style="text-align:center;">高</td><td style="text-align:center;"><strong>最高</strong></td><td style="text-align:center;">中</td><td style="text-align:center;">中</td><td style="text-align:center;">低（Java版新）</td></tr></tbody></table><hr><h2 id="三、langchain4j-vs-spring-ai-alibaba-深入对比" tabindex="-1">三、LangChain4j vs Spring AI Alibaba 深入对比 <a class="header-anchor" href="#三、langchain4j-vs-spring-ai-alibaba-深入对比" aria-label="Permalink to &quot;三、LangChain4j vs Spring AI Alibaba 深入对比&quot;">​</a></h2><p>这是选型中最常见的二选一问题。</p><h3 id="定位不同" tabindex="-1">定位不同 <a class="header-anchor" href="#定位不同" aria-label="Permalink to &quot;定位不同&quot;">​</a></h3><ul><li><strong>LangChain4j</strong>：LLM 集成工具箱。核心能力是&quot;统一 API 接入 20+ 模型&quot; + &quot;AI Services 声明式调用&quot; + &quot;RAG 管道&quot;。目标是<strong>让 Java 开发者方便地使用 LLM</strong>。</li><li><strong>Spring AI Alibaba</strong>：AI 智能体应用平台。核心能力是&quot;多 Agent 编排&quot; + &quot;Graph 工作流&quot; + &quot;企业级运维&quot;。目标是<strong>让 Java 开发者构建生产级 Agent 系统</strong>。</li></ul><h3 id="多智能体——最大分水岭" tabindex="-1">多智能体——最大分水岭 <a class="header-anchor" href="#多智能体——最大分水岭" aria-label="Permalink to &quot;多智能体——最大分水岭&quot;">​</a></h3><p>这是两者最大的差异点。LangChain4j 没有原生的多 Agent 编排能力，需要自己写调度逻辑：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// LangChain4j：多 Agent 需要手写调度</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">String result1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> agent1.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(input);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">String result2 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> agent2.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(result1);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">String final </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> supervisor.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(result2);</span></span></code></pre></div><p>Spring AI Alibaba 声明式配置即可：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Spring AI Alibaba：声明式多 Agent</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pipeline </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SequentialAgent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(List.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">of</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(agent1, agent2, agent3));</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pipeline.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">call</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(input);</span></span></code></pre></div><p>如果需求只是&quot;一个 Chat + RAG&quot;，LangChain4j 完全足够。如果需要多个 Agent 协作（比如一个查订单、一个查物流、一个汇总），Spring AI Alibaba 优势明显。</p><h3 id="模型接入" tabindex="-1">模型接入 <a class="header-anchor" href="#模型接入" aria-label="Permalink to &quot;模型接入&quot;">​</a></h3><p>LangChain4j 完胜。它的统一 API 设计使得切换模型只需换 Builder，代码零改动。Spring AI Alibaba 的核心模型是 DashScope（百炼），虽然能接 OpenAI 但不是一等公民。</p><h3 id="企业级能力" tabindex="-1">企业级能力 <a class="header-anchor" href="#企业级能力" aria-label="Permalink to &quot;企业级能力&quot;">​</a></h3><p>Spring AI Alibaba 有 LangChain4j 没有的：Docker 安全沙箱、A2A 分布式协作（基于 Nacos）、RocketMQ 会话持久化、Admin 可视化运维。这些在生产环境中是硬需求，不是 nice to have。</p><h3 id="框架关系图" tabindex="-1">框架关系图 <a class="header-anchor" href="#框架关系图" aria-label="Permalink to &quot;框架关系图&quot;">​</a></h3><p>这些框架并非互斥，而是有明确的层次关系：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        Spring AI（标准抽象层）</span></span>
<span class="line"><span>             ↓</span></span>
<span class="line"><span>   ┌────────┼────────┐</span></span>
<span class="line"><span>   ↓        ↓        ↓</span></span>
<span class="line"><span>LangChain4j  Spring AI Alibaba  ...</span></span>
<span class="line"><span>   (模型集成)   ↓</span></span>
<span class="line"><span>          AgentScope Java</span></span>
<span class="line"><span>          (多Agent运行时引擎)</span></span></code></pre></div><p>Spring AI 提供 ChatClient / Tool / MCP 等标准抽象，LangChain4j 通过 Spring AI 的抽象接入，Spring AI Alibaba 在 Spring AI 之上叠加多 Agent 编排，AgentScope Java 作为底层引擎。</p><hr><h2 id="四、技术选型决策树" tabindex="-1">四、技术选型决策树 <a class="header-anchor" href="#四、技术选型决策树" aria-label="Permalink to &quot;四、技术选型决策树&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>需要多 Agent 协作？</span></span>
<span class="line"><span>  ├── 是 → 已经在用阿里云？</span></span>
<span class="line"><span>  │         ├── 是 → Spring AI Alibaba</span></span>
<span class="line"><span>  │         └── 否 → AgentScope Java（独立使用，不绑Spring）</span></span>
<span class="line"><span>  └── 否 → 需要灵活切换模型提供商？</span></span>
<span class="line"><span>            ├── 是 → LangChain4j</span></span>
<span class="line"><span>            └── 否 → 绑 Google 生态？</span></span>
<span class="line"><span>                      ├── 是 → Google ADK</span></span>
<span class="line"><span>                      └── 否 → Spring AI 裸用 或 LangChain4j</span></span></code></pre></div><h3 id="各场景推荐" tabindex="-1">各场景推荐 <a class="header-anchor" href="#各场景推荐" aria-label="Permalink to &quot;各场景推荐&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>推荐</th><th>理由</th></tr></thead><tbody><tr><td>Spring Boot 加个 Chat + RAG</td><td><strong>LangChain4j</strong></td><td>最简单，成熟度最高</td></tr><tr><td>多 Agent 协作，已用阿里云</td><td><strong>Spring AI Alibaba</strong></td><td>生态协同，开箱即用</td></tr><tr><td>多 Agent 协作，不绑阿里云</td><td><strong>AgentScope Java</strong></td><td>独立框架，轻量</td></tr><tr><td>仅需标准 LLM 集成，不绑特定提供商</td><td><strong>Spring AI</strong></td><td>Spring 官方，抽象最标准</td></tr><tr><td>Google Cloud 全家桶</td><td><strong>Google ADK</strong></td><td>Gemini + Firestore + Vertex AI 深度集成</td></tr></tbody></table><hr><h2 id="五、避坑指南" tabindex="-1">五、避坑指南 <a class="header-anchor" href="#五、避坑指南" aria-label="Permalink to &quot;五、避坑指南&quot;">​</a></h2><h3 id="_1-不要因为-阿里-google-背书-就无脑选" tabindex="-1">1. 不要因为&quot;阿里/Google 背书&quot;就无脑选 <a class="header-anchor" href="#_1-不要因为-阿里-google-背书-就无脑选" aria-label="Permalink to &quot;1. 不要因为&quot;阿里/Google 背书&quot;就无脑选&quot;">​</a></h3><p>如果需求就是一个 Chat + RAG，LangChain4j 比 Spring AI Alibaba 更简单、更稳。大厂的 AI 框架迭代极快，API 随时可能变。</p><h3 id="_2-不要低估企业级需求的复杂度" tabindex="-1">2. 不要低估企业级需求的复杂度 <a class="header-anchor" href="#_2-不要低估企业级需求的复杂度" aria-label="Permalink to &quot;2. 不要低估企业级需求的复杂度&quot;">​</a></h3><p>安全沙箱、会话持久化、人工审批——这些 LangChain4j 都没有内置。如果真要上生产，自研成本要提前算清楚。AgentScope Java 在这方面投入最重。</p><h3 id="_3-版本兼容矩阵要提前查" tabindex="-1">3. 版本兼容矩阵要提前查 <a class="header-anchor" href="#_3-版本兼容矩阵要提前查" aria-label="Permalink to &quot;3. 版本兼容矩阵要提前查&quot;">​</a></h3><p>Spring AI Alibaba 依赖 Spring AI，而 Spring AI 2.0 M2 已经出了，API 还在演进。选型时要锁定具体版本组合，避免升级踩坑。</p><h3 id="_4-混用是可以的-但一般不推荐" tabindex="-1">4. 混用是可以的，但一般不推荐 <a class="header-anchor" href="#_4-混用是可以的-但一般不推荐" aria-label="Permalink to &quot;4. 混用是可以的，但一般不推荐&quot;">​</a></h3><p>Spring AI Alibaba v1.1.2.2 底层用了 AgentScope Java，而上层通过 Spring AI 抽象可以和 LangChain4j 共存。但维护两套依赖、两套 API 心智负担重，除非有明确理由（如 LangChain4j 的某个模型集成 Spring AI 没有）。</p><h3 id="_5-google-adk-java-版还很新" tabindex="-1">5. Google ADK Java 版还很新 <a class="header-anchor" href="#_5-google-adk-java-版还很新" aria-label="Permalink to &quot;5. Google ADK Java 版还很新&quot;">​</a></h3><p>v1.0 2026 年 3 月才出，社区积累少。如果有生产时间压力，先观望或直接用 Python 版。</p><h3 id="_6-关注-spring-ai-本身的定位变化" tabindex="-1">6. 关注 Spring AI 本身的定位变化 <a class="header-anchor" href="#_6-关注-spring-ai-本身的定位变化" aria-label="Permalink to &quot;6. 关注 Spring AI 本身的定位变化&quot;">​</a></h3><p>Spring AI 是底层抽象，Spring AI Alibaba 是上层实现。如果 Spring AI 2.0 把多 Agent 编排纳入标准抽象，Spring AI Alibaba 的差异化会缩小。持续关注社区路线图。</p><hr><h2 id="六、相关笔记" tabindex="-1">六、相关笔记 <a class="header-anchor" href="#六、相关笔记" aria-label="Permalink to &quot;六、相关笔记&quot;">​</a></h2><ul><li><a href="/java-site/框架/AI 框架/Spring AI/">框架 Spring AI</a> — Spring 官方 AI 标准抽象</li><li><a href="/java-site/框架/AI 框架/Spring AI Alibaba.html">框架 Spring AI Alibaba</a> — 阿里 Agentic AI 平台</li><li><a href="/java-site/框架/AI 框架/LangChain4j.html">框架 LangChain4j</a> — JVM LLM 集成工具箱</li><li><a href="/java-site/框架/AI 框架/AgentScope Java.html">框架 Agentscope-java</a> — 企业级多智能体引擎</li><li><a href="/java-site/框架/AI 框架/Google ADK (Agent Development Kit).html">框架 Google ADK</a> — Google 多语言 Agent SDK</li></ul>`,51)])])}const A=a(s,[["render",l]]);export{c as __pageData,A as default};
